schema.content:
Table "alignment" {
  "id" INTEGER [pk, not null]
  "alignment" TEXT
}

Table "attribute" {
  "id" INTEGER [pk, not null]
  "attribute_name" TEXT
}

Table "colour" {
  "id" INTEGER [pk, not null]
  "colour" TEXT
}

Table "gender" {
  "id" INTEGER [pk, not null]
  "gender" TEXT
}

Table "hero_attribute" {
  "hero_id" INTEGER
  "attribute_id" INTEGER
  "attribute_value" INTEGER
}

Table "hero_power" {
  "hero_id" INTEGER
  "power_id" INTEGER
}

Table "publisher" {
  "id" INTEGER [pk, not null]
  "publisher_name" TEXT
}

Table "race" {
  "id" INTEGER [pk, not null]
  "race" TEXT
}

Table "superhero" {
  "id" INTEGER [pk, not null]
  "superhero_name" TEXT
  "full_name" TEXT
  "gender_id" INTEGER
  "eye_colour_id" INTEGER
  "hair_colour_id" INTEGER
  "skin_colour_id" INTEGER
  "race_id" INTEGER
  "publisher_id" INTEGER
  "alignment_id" INTEGER
  "height_cm" INTEGER
  "weight_kg" INTEGER
}

Table "superpower" {
  "id" INTEGER [pk, not null]
  "power_name" TEXT
}



